"from bs4 import BeautifulSoup\n\nwith open('tests/workday/Systems Software Engineer - New College Grad 2026.htm', 'r', encoding='utf-8', errors='ignore') as f:\n    soup = BeautifulSoup(f.read(), 'html.parser')\n\nfor inp in soup.find_all('input'):\n    iid = inp.get('id', '')\n    aid = inp.get('data-automation-id', '')\n    aria = inp.get('aria-label', '')\n    if any(k in (iid + aid + aria).lower() for k in ['date', 'month', 'year']):\n        print(f\"id='{iid}', aid='{aid}', aria='{aria}', class='{inp.get('class')}'\")\n"